package org.firstinspires.ftc.teamcode.tuning;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.DcMotorSimple;

import org.firstinspires.ftc.teamcode.config.DeviceNames;

import java.util.Locale;

// Generated by refract-suite ftc-construct. PRACTICE ONLY. Setup program 2 (prerequisites E-3, E-4).
// Runs the intake and each flywheel slowly while R2 is held and asks which way they went. Drive motors are
// done by Pedro's Mecanum Tuner (program 5) and the yaw by the Yaw Tuner (program 3). Afterwards it is a
// free jog for any motor.
@TeleOp(name = "2 Motor Directions", group = "19859 Setup")
public class MotorJog extends LinearOpMode {
    private static final double TEST_POWER = 0.3;
    private static final double FREE_JOG_MAX_POWER = 0.3;
    private static final double MOVING_TICKS_PER_S = 20;

    private static final String[] TEST_MOTORS = {DeviceNames.INTAKE, DeviceNames.FRONT_FLYWHEEL, DeviceNames.BACK_FLYWHEEL};
    private static final String[] TEST_TITLES = {"Intake direction", "Front flywheel direction", "Back flywheel direction"};
    private static final String[] TEST_QUESTIONS = {
            "Did the intake pull elements IN?",
            "Did the front flywheel surface move the way that would throw an element OUT?",
            "Did the back flywheel surface move the way that would throw an element OUT?"};
    private static final String[] RESULT_KEYS = {"intakeReversed", "frontFlywheelReversed", "backFlywheelReversed"};
    private static final String[] JOG_MOTORS = {DeviceNames.INTAKE, DeviceNames.FRONT_FLYWHEEL, DeviceNames.BACK_FLYWHEEL,
            DeviceNames.YAW, DeviceNames.LEFT_FRONT, DeviceNames.LEFT_BACK, DeviceNames.RIGHT_FRONT, DeviceNames.RIGHT_BACK};

    @Override
    public void runOpMode() {
        Guide g = new Guide(telemetry, 2);
        DcMotorEx[] tests = new DcMotorEx[TEST_MOTORS.length];
        StringBuilder missing = new StringBuilder();
        for (int i = 0; i < TEST_MOTORS.length; i++) tests[i] = motor(TEST_MOTORS[i], missing);
        DcMotorEx[] jog = new DcMotorEx[JOG_MOTORS.length];
        for (int i = 0; i < JOG_MOTORS.length; i++) jog[i] = motor(JOG_MOTORS[i], new StringBuilder());

        while (opModeInInit()) {
            g.header(0, 0, "Before you start");
            g.why("Plus power must pull elements in (intake) and throw them out (flywheels). If not, the code reverses that motor.");
            if (missing.length() > 0) g.notReady("device names " + missing + "(program 1)");
            g.doThis("Robot on a box. Keep hands clear of the intake and flywheels.");
            g.say("Each test spins one part slowly (30%) only while you HOLD R2.");
            g.doThis("Press START.");
            g.update();
        }
        if (isStopRequested() || missing.length() > 0) return;

        int step = 0;
        int[] velocitySign = new int[TEST_MOTORS.length];
        boolean[] ran = new boolean[TEST_MOTORS.length];
        boolean done = false;
        int jogIndex = 0;
        String note = "", backwards = "";

        while (opModeIsActive()) {
            boolean yes = gamepad1.crossWasPressed(), no = gamepad1.circleWasPressed(), back = gamepad1.triangleWasPressed();
            boolean nextJog = gamepad1.dpadUpWasPressed(), previousJog = gamepad1.dpadDownWasPressed();

            if (!backwards.isEmpty()) {
                g.header(0, 0, "Stopped");
                g.encoderBackwards(backwards);
            } else if (!done) {
                if (back && step > 0) {
                    tests[step].setPower(0);
                    step--;
                }
                DcMotorEx m = tests[step];
                boolean run = gamepad1.right_trigger > 0.5;
                m.setPower(run ? TEST_POWER : 0);
                double velocity = m.getVelocity();
                if (run) ran[step] = true;
                if (run && Math.abs(velocity) > MOVING_TICKS_PER_S) velocitySign[step] = velocity > 0 ? 1 : -1;
                // the intake may have no encoder wired; flywheels must show the encoder counting
                boolean answered = step == 0 ? ran[step] : velocitySign[step] != 0;

                g.header(step + 1, TEST_MOTORS.length, TEST_TITLES[step]);
                g.why("Tells the code whether this motor has to be reversed.");
                g.goal("You saw it clearly and answered yes or no.");
                g.doThis("HOLD R2 and watch it.");
                g.say(TEST_QUESTIONS[step]);
                g.value("Power / encoder", String.format(Locale.US, "%.1f / %.0f ticks/s", m.getPower(), velocity));
                g.keys("cross = YES, circle = NO" + (step > 0 ? ", triangle = back" : ""));
                if ((yes || no) && !answered) {
                    note = step == 0 ? "hold R2 first, then answer" : "hold R2 until it spins (encoder must count), then answer";
                } else if (yes || no) {
                    m.setPower(0);
                    note = "";
                    boolean reversed = no;
                    note = g.record(RESULT_KEYS[step], String.valueOf(reversed));
                    // REVERSE flips both the power and the encoder reading, so once the direction is set right,
                    // + power reads back with the same sign it had here: it must be +
                    boolean encoderOpposite = velocitySign[step] < 0;
                    if (step > 0) g.record(RESULT_KEYS[step].replace("Reversed", "EncoderOpposite"), String.valueOf(encoderOpposite));
                    // the hub's speed control would run this flywheel away: stop until the wiring is fixed
                    if (step > 0 && encoderOpposite) backwards = (step == 1 ? "front" : "back") + " flywheel";
                    step++;
                    if (step >= TEST_MOTORS.length && backwards.isEmpty()) {
                        done = true;
                        g.loadNextOnStop(this);
                    }
                }
            } else {
                if (nextJog || previousJog) {
                    if (jog[jogIndex] != null) jog[jogIndex].setPower(0);
                    jogIndex = (jogIndex + (nextJog ? 1 : JOG_MOTORS.length - 1)) % JOG_MOTORS.length;
                }
                double power = (gamepad1.right_trigger - gamepad1.left_trigger) * FREE_JOG_MAX_POWER;
                DcMotorEx m = jog[jogIndex];
                if (m != null) m.setPower(power);
                g.header(0, 0, "Done");
                g.finished("");
                g.say("Free jog (optional): dpad up/down picks a motor, R2 / L2 run it + / -.");
                g.value("Motor", JOG_MOTORS[jogIndex] + (m == null ? " (not in config)" : ""));
                if (m != null) g.value("Power / encoder", String.format(Locale.US, "%.2f / %d ticks", power, m.getCurrentPosition()));
            }
            if (!note.isEmpty()) g.warn(note);
            g.update();
        }
        for (DcMotorEx m : jog) if (m != null) m.setPower(0);
    }

    private DcMotorEx motor(String name, StringBuilder missing) {
        try {
            DcMotorEx m = hardwareMap.get(DcMotorEx.class, name);
            m.setDirection(DcMotorSimple.Direction.FORWARD);
            m.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
            m.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.FLOAT);
            return m;
        } catch (IllegalArgumentException e) {
            missing.append(name).append(' ');
            return null;
        }
    }
}
